import{_ as s,a0 as o,w as p,s as l,ao as b,I as a,x as u,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"每日Ubuntu小技巧——安装Ubuntu后做什么 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧——安装Ubuntu后做什么 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧——安装Ubuntu后做什么 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧——安装Ubuntu后做什么 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Daily Ubuntu Tips–Things To Do After Installing Ubuntu","title":"每日Ubuntu小技巧——安装Ubuntu后做什么","tag":"201310","desc":""},"relativePath":"201310/Daily Ubuntu Tips–Things To Do After Installing Ubuntu.md","filePath":"[post].md"}'),r={name:"201310/Daily Ubuntu Tips–Things To Do After Installing Ubuntu.md"};function d(U,t,T,g,m,f){const n=o("Link");return p(),l("div",null,[t[11]||(t[11]=b('<h1 id="每日ubuntu小技巧——安装ubuntu后做什么" tabindex="-1">每日Ubuntu小技巧——安装Ubuntu后做什么 <a class="header-anchor" href="#每日ubuntu小技巧——安装ubuntu后做什么" aria-label="Permalink to “每日Ubuntu小技巧——安装Ubuntu后做什么”">​</a></h1><p>许多Windows用户开始使用Ubuntu时都感到束手无策。Ubuntu与Windows截然不同，想要轻松驾驭Ubuntu可不是一件简单的事情。Ubuntu的使用方式不同于Windows。许多用户对命令行、文件系统的布局和应用程序的名称都感到陌生。但是不用担心，我们会提供帮助的。</p><p>如果你以前是Windows或者Mac OS X用户现在想学Ubuntu，那你来对地方了。我们正努力帮助新用户开始Ubuntu之旅。我们的口号理所当然就是“<strong>菜鸟教程</strong>”。</p><p>我们的教程大多不是针对专业人士的，而是面向刚开始学习Windows和Ubuntu的新手。所以，在Ubuntu上遇到了任何困扰，都可以回来转转。</p><p>好了，言归正传。几天前一个读者问了我们一个问题，如下：</p><blockquote><p>安装好Ubuntu后首先要做什么？</p></blockquote><p>很简单，第一次安装Ubuntu时，你可能有很多事情想做。但是最重要的是让它正常工作。不要担心遇到难题，这些你很快就会明白。</p><p>这里有一些安装好Ubuntu之后你最初想要做的事。可能你想做的比这还多，但这些是比较重要的。</p><ul><li><p>更新系统 －首先更新你的系统。系统更新可以让你安装比较新的软件包和一些其它程序的修正。使用Ubuntu时你可以使用下面的命令正确地进行系统更新。</p><p>sudo apt-get update &amp;&amp; sudo apt-get dist-upgrade &amp;&amp; sudo apt-get autoremove</p></li><li><p>安装好Ubuntu后要做的另外一件事就是运行下面的命令。这条命令能帮助你安装编解码器和因法律原因而排除在Ubuntu外的软件包。Ubuntu并未预装这些比较重要的程序。而没有这些程序你可能无法听音乐、看电影或者做其它的事情。所以，如果你安装了Ubuntu但是不能播放DVD或者听音乐CD，那就运行下面的命令吧。</p><p>sudo apt-get install ubuntu-restricted-extras</p></li></ul><p>以上这些命令并非你将在Ubuntu运行的全部的命令，但它们是安装好Ubuntu后你首先要运行的。希望这些能帮助到你。</p><p>使用愉快！</p><hr>',12)),a("p",null,[t[1]||(t[1]=u("via: ",-1)),e(n,{href:"http://www.liberiangeek.net/2013/10/daily-ubuntu-tipsthings-to-do-after-installing-ubuntu/"},{default:i(()=>[...t[0]||(t[0]=[u("http://www.liberiangeek.net/2013/10/daily-ubuntu-tipsthings-to-do-after-installing-ubuntu/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=u("译者：",-1)),e(n,{href:"https://github.com/Linchenguang"},{default:i(()=>[...t[2]||(t[2]=[u("Linchenguang",-1)])]),_:1}),t[5]||(t[5]=u(" 校对：",-1)),e(n,{href:"https://github.com/carolinewuyan"},{default:i(()=>[...t[3]||(t[3]=[u("Caroline",-1)])]),_:1})]),a("p",null,[t[8]||(t[8]=u("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[6]||(t[6]=[u("LCTT",-1)])]),_:1}),t[9]||(t[9]=u(" 原创翻译，",-1)),e(n,{href:"http://linux.cn/"},{default:i(()=>[...t[7]||(t[7]=[u("Linux中国",-1)])]),_:1}),t[10]||(t[10]=u(" 荣誉推出",-1))])])}const _=s(r,[["render",d]]);export{w as __pageData,_ as default};
